import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CeXt7FPx.js";const c=JSON.parse('{"title":"Mail","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mail.md","filePath":"guide/mail.md"}'),n={name:"guide/mail.md"};function l(h,s,p,r,d,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h1><p>Tiffin catches every email your apps send, on <code>127.0.0.1:2525</code>, and keeps it for you to read. Nothing is ever delivered.</p><h2 id="php-sends-here-by-itself" tabindex="-1">PHP sends here by itself <a class="header-anchor" href="#php-sends-here-by-itself" aria-label="Permalink to &quot;PHP sends here by itself&quot;">​</a></h2><p>Sites Tiffin serves have PHP&#39;s <code>mail()</code> pointed at the catcher, so apps that use it need no setting. For Laravel&#39;s SMTP mailer, in <code>.env</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MAIL_MAILER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">smtp</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MAIL_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MAIL_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2525</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MAIL_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">null</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MAIL_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">null</span></span></code></pre></div><p>Any other program can send to <code>127.0.0.1:2525</code> the same way: plain SMTP, no password.</p><h2 id="read-it" tabindex="-1">Read it <a class="header-anchor" href="#read-it" aria-label="Permalink to &quot;Read it&quot;">​</a></h2><p>The app&#39;s <strong>Mail</strong> screen shows each message as it would look (HTML, text, headers or the raw message) and its attachments. The tray menu counts unread mail, and the tray icon shows a small dot while any is unread, so you see it arrive without opening anything. Or in a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # the newest first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # --html for the HTML source, --raw for the message as received</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> save</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> invoice.pdf</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # save an attachment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span></span></code></pre></div><p>Messages are kept on disk in Tiffin&#39;s data folder until you delete them.</p><div class="tip custom-block"><p class="custom-block-title">Port 2525 already in use?</p><p>Another mail catcher (Mailpit, Herd&#39;s, Yerd&#39;s) may be on it. Stop it, or move Tiffin&#39;s: <code>tiffin config set mail 127.0.0.1:2526 --restart</code>, or <strong>Settings &gt; Ports</strong> in the app (<a href="/tiffin/guide/troubleshooting#a-port-is-already-in-use">A port is already in use</a>).</p></div>`,11)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
